 namespace std { inline namespace __1 {



namespace ranges {
template <class _InIter1, class _Func1>
struct in_fun_result {
  [[__no_unique_address__]] _InIter1 in;
  [[__no_unique_address__]] _Func1 fun;

  template <class _InIter2, class _Func2>
    requires convertible_to<const _InIter1&, _InIter2> && convertible_to<const _Func1&, _Func2>
  __attribute__((__exclude_from_explicit_instantiation__)) __attribute__((__abi_tag__("ne210107"))) constexpr operator in_fun_result<_InIter2, _Func2>() const& {
    return {in, fun};
  }

  template <class _InIter2, class _Func2>
    requires convertible_to<_InIter1, _InIter2> && convertible_to<_Func1, _Func2>
  __attribute__((__exclude_from_explicit_instantiation__)) __attribute__((__abi_tag__("ne210107"))) constexpr operator in_fun_result<_InIter2, _Func2>() && {
    return {std::move(in), std::move(fun)};
  }
};
} // namespace ranges



} }
