    if (__first == __last)
      std::__throw_regex_error<regex_constants::error_brack>();
    if (*__first == '-') {
      __ml->__add_char('-');
      ++__first;
    }
    if (__first == __last || *__first != ']')
      std::__throw_regex_error<regex_constants::error_brack>();
    ++__first;
