static __inline unsigned int __get_cpuid_max (unsigned int __leaf,
                                              unsigned int *__sig)
{
    unsigned int __eax, __ebx, __ecx, __edx;
# 312 "D:/Code/Msys2/Files/clang64/lib/clang/21/include/cpuid.h" 3
    __asm("  xchg{q|}  {%%|}rbx,%q1\n" "  cpuid\n" "  xchg{q|}  {%%|}rbx,%q1" : "=a"(__eax), "=r"(__ebx), "=c"(__ecx), "=d"(__edx) : "0"(__leaf));
    if (__sig)
        *__sig = __ebx;
    return __eax;
}

static __inline int __get_cpuid (unsigned int __leaf, unsigned int *__eax,
                                 unsigned int *__ebx, unsigned int *__ecx,
                                 unsigned int *__edx)
{
    unsigned int __max_leaf = __get_cpuid_max(__leaf & 0x80000000, 0);

    if (__max_leaf == 0 || __max_leaf < __leaf)
        return 0;

    __asm("  xchg{q|}  {%%|}rbx,%q1\n" "  cpuid\n" "  xchg{q|}  {%%|}rbx,%q1" : "=a"(*__eax), "=r"(*__ebx), "=c"(*__ecx), "=d"(*__edx) : "0"(__leaf));
    return 1;
}

static __inline int __get_cpuid_count (unsigned int __leaf,
                                       unsigned int __subleaf,
                                       unsigned int *__eax, unsigned int *__ebx,
                                       unsigned int *__ecx, unsigned int *__edx)
{
    unsigned int __max_leaf = __get_cpuid_max(__leaf & 0x80000000, 0);

    if (__max_leaf == 0 || __max_leaf < __leaf)
        return 0;

    __asm("  xchg{q|}  {%%|}rbx,%q1\n" "  cpuid\n" "  xchg{q|}  {%%|}rbx,%q1" : "=a"(*__eax), "=r"(*__ebx), "=c"(*__ecx), "=d"(*__edx) : "0"(__leaf), "2"(__subleaf));
    return 1;
}

// In some configurations, __cpuidex is defined as a builtin (primarily
// -fms-extensions) which will conflict with the __cpuidex definition below.

static __inline void __cpuidex(int __cpu_info[4], int __leaf, int __subleaf) {
  __asm("  xchg{q|}  {%%|}rbx,%q1\n" "  cpuid\n" "  xchg{q|}  {%%|}rbx,%q1" : "=a"(__cpu_info[0]), "=r"(__cpu_info[1]), "=c"(__cpu_info[2]), "=d"(__cpu_info[3]) : "0"(__leaf), "2"(__subleaf));

}
